/* Deutsch Trainer Reading II — curated, CEFR-differentiated texts. Original parallel Italian translations. */
const DT_READING2_BANK=[{"id":"R3-A1-001","level":"A1","title":"Eine Nachricht von Mia","genre":"messaggio personale","equivalents":{"it":[["sono mia","io sono mia"],["dodici","12"],["in autobus","con il bus","col bus"],["la fermata","la fermata dell'autobus"],["proprio davanti alla casa","immediatamente davanti alla casa"],["da mangiare","il cibo"],["ho pane","ho il pane"],["dorme spesso sotto il tavolo","lui dorme spesso sotto il tavolo"],["allora bruno resta","così bruno rimane"],["sul balcone","in balcone"]]},"sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Hallo Ben! Ich bin Mia. Ich bin heute zu Hause. Am Samstag habe ich Zeit. Kommst du um drei Uhr zu mir? Meine Adresse ist Gartenstraße zwölf. Ich wohne im zweiten Stock. Meine Wohnung ist klein, aber schön.","Ciao Ben! Sono Mia. Oggi sono a casa. Sabato ho tempo. Vieni da me alle tre? Il mio indirizzo è Gartenstraße dodici. Abito al secondo piano. Il mio appartamento è piccolo, ma bello."],["Du kannst mit dem Bus kommen. Die Haltestelle ist direkt vor dem Haus. Bring bitte kein Essen mit. Ich habe Brot, Käse und Obst. Wir trinken Tee und hören Musik. Schreib mir bitte heute Abend. Bis Samstag!","Puoi venire in autobus. La fermata è proprio davanti alla casa. Per favore non portare da mangiare. Ho pane, formaggio e frutta. Beviamo tè e ascoltiamo musica. Scrivimi stasera, per favore. A sabato!"],["Mein Hund heißt Bruno. Er ist sehr freundlich. Er schläft oft unter dem Tisch. Wenn du Angst vor Hunden hast, sag es mir bitte. Dann bleibt Bruno im Garten. Ich habe auch zwei Stühle auf dem Balkon.","Il mio cane si chiama Bruno. È molto amichevole. Dorme spesso sotto il tavolo. Se hai paura dei cani, dimmelo per favore. Allora Bruno resta in giardino. Ho anche due sedie sul balcone."]]},{"id":"R3-A1-002","level":"A1","title":"Im kleinen Obstladen","genre":"dialogo in negozio","equivalents":{"it":[["commessa","negoziante","venditrice"],["vuole","vorrebbe"],["delle arance","le arance"],["sono sei euro","in tutto fanno sei euro"],["vuole un sacchetto","desidera una busta"],["tornano a casa insieme","vanno insieme a casa","loro vanno insieme a casa"],["preparano una macedonia","fanno la macedonia","preparano la macedonia"],["vengono a trovarli","vengono a visitarli"],["ecco la sua frutta","ecco qui la sua frutta"]]},"sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Verkäuferin: Guten Morgen! Was möchten Sie? Kunde: Ich möchte vier Äpfel und zwei Bananen. Verkäuferin: Möchten Sie auch Orangen? Heute sind sie frisch. Kunde: Ja, bitte drei Orangen. Was kostet das zusammen? Verkäuferin: Das macht sechs Euro und fünfzig Cent.","Commessa: Buongiorno! Che cosa desidera? Cliente: Vorrei quattro mele e due banane. Commessa: Vuole anche delle arance? Oggi sono fresche. Cliente: Sì, tre arance per favore. Quanto costa tutto insieme? Commessa: Sono sei euro e cinquanta centesimi."],["Kunde: Kann ich mit Karte bezahlen? Verkäuferin: Ja, natürlich. Möchten Sie eine Tüte? Kunde: Nein, danke. Ich habe eine Tasche. Verkäuferin: Hier ist Ihr Obst. Einen schönen Tag! Kunde: Danke, Ihnen auch!","Cliente: Posso pagare con la carta? Commessa: Sì, certamente. Vuole un sacchetto? Cliente: No, grazie. Ho una borsa. Commessa: Ecco la sua frutta. Buona giornata! Cliente: Grazie, anche a lei!"],["Draußen ist es kalt. Der Kunde zieht seine Jacke an. Vor dem Laden wartet seine Schwester. Sie gehen zusammen nach Hause. Dort machen sie einen Obstsalat. Am Abend kommen zwei Freunde zu Besuch.","Fuori fa freddo. Il cliente si mette la giacca. Davanti al negozio lo aspetta sua sorella. Tornano a casa insieme. Lì preparano una macedonia. La sera vengono a trovarli due amici."]]},{"id":"R3-A1-003","level":"A1","title":"Ein Tag in der Sprachschule","genre":"racconto quotidiano","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Omar lernt Deutsch. Sein Kurs beginnt um neun Uhr. Er steht um sieben Uhr auf und frühstückt mit seiner Schwester. Dann fährt er mit dem Fahrrad zur Schule. Heute sind zwölf Personen im Kurs. Die Lehrerin heißt Frau Weber.","Omar studia tedesco. Il suo corso inizia alle nove. Si alza alle sette e fa colazione con sua sorella. Poi va a scuola in bicicletta. Oggi ci sono dodici persone nel corso. L’insegnante si chiama signora Weber."],["Die Gruppe liest einen kurzen Text. Danach schreiben alle fünf Sätze. In der Pause trinkt Omar Wasser und spricht mit einem Freund. Um zwölf Uhr ist der Kurs zu Ende. Zu Hause macht er seine Hausaufgaben.","Il gruppo legge un testo breve. Dopo tutti scrivono cinque frasi. Durante la pausa Omar beve acqua e parla con un amico. Alle dodici il corso finisce. A casa fa i compiti."],["Heute lernt Omar neue Wörter: die Schule, das Heft, das Buch und der Stift. Er schreibt die Wörter in eine Liste. Seine Schwester fragt am Abend: Wie war dein Tag? Omar sagt: Sehr gut!","Oggi Omar impara nuove parole: la scuola, il quaderno, il libro e la penna. Scrive le parole in una lista. Sua sorella chiede la sera: Com’è andata la giornata? Omar risponde: Molto bene!"]]},{"id":"R3-A1-004","level":"A1","title":"Eine Einladung zum Geburtstag","genre":"invito","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Liebe Freunde, am Freitag habe ich Geburtstag! Ich werde dreißig Jahre alt. Ich mache eine kleine Party bei mir zu Hause. Wir beginnen um achtzehn Uhr. Es gibt Pizza, Salat, Saft und Kuchen. Mein Bruder bringt Musik mit.","Cari amici, venerdì è il mio compleanno! Compio trent’anni. Faccio una piccola festa a casa mia. Iniziamo alle diciotto. Ci saranno pizza, insalata, succo e torta. Mio fratello porta la musica."],["Bitte sagt mir bis Mittwoch Bescheid: Kommt ihr allein oder mit einer Person? Ich habe Platz für zehn Gäste. Mein Haus ist neben der Post. Die Tür ist blau. Ich freue mich auf euch! Viele Grüße, Lisa.","Per favore fatemi sapere entro mercoledì: venite da soli o con un’altra persona? Ho posto per dieci ospiti. La mia casa è accanto alla posta. La porta è blu. Non vedo l’ora di vedervi! Un saluto, Lisa."],["Die Party ist im Wohnzimmer. Im Garten stehen auch ein Tisch und vier Stühle. Bei gutem Wetter können wir draußen sitzen. Meine Nachbarin kommt ebenfalls. Sie bringt Saft mit. Wir spielen später ein kleines Spiel.","La festa è in soggiorno. In giardino ci sono anche un tavolo e quattro sedie. Se fa bel tempo possiamo sederci fuori. Viene anche la mia vicina. Porta del succo. Più tardi facciamo un piccolo gioco."]]},{"id":"R3-A1-005","level":"A1","title":"Der Bus kommt später","genre":"avviso e dialogo","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["An der Haltestelle steht ein Schild: Bus Nummer sieben kommt heute zehn Minuten später. Anna liest den Text. Sie muss um neun Uhr im Büro sein. Jetzt ist es acht Uhr zwanzig. Anna hat noch Zeit. Neben ihr wartet ein Mann.","Alla fermata c’è un cartello: oggi l’autobus numero sette arriva dieci minuti più tardi. Anna legge il testo. Deve essere in ufficio alle nove. Ora sono le otto e venti. Anna ha ancora tempo. Accanto a lei aspetta un uomo."],["Anna: Fährt dieser Bus zum Bahnhof? Mann: Ja, aber erst um halb neun. Anna: Danke. Wie lange dauert die Fahrt? Mann: Etwa fünfzehn Minuten. Anna: Gut, dann komme ich pünktlich an. Mann: Da ist schon der Bus!","Anna: Questo autobus va alla stazione? Uomo: Sì, ma solo alle otto e mezza. Anna: Grazie. Quanto dura il viaggio? Uomo: Circa quindici minuti. Anna: Bene, allora arrivo puntuale. Uomo: Ecco già l’autobus!"],["Im Bus sitzen heute nur wenige Personen. Anna findet einen Platz am Fenster. Sie sieht Häuser, Geschäfte und einen Park. Nach drei Haltestellen steigt sie aus. Von dort geht sie fünf Minuten zu Fuß zum Büro.","Oggi sull’autobus siedono poche persone. Anna trova un posto vicino al finestrino. Vede case, negozi e un parco. Dopo tre fermate scende. Da lì cammina cinque minuti fino all’ufficio."]]},{"id":"R3-A1-006","level":"A1","title":"Mein Zimmer und meine Sachen","genre":"descrizione","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Ich heiße David und wohne mit meiner Mutter in einem Haus. Mein Zimmer ist oben, neben dem Bad. Es ist nicht groß. Links steht mein Bett. Rechts ist ein Tisch mit einem Computer. Auf dem Tisch liegen drei Bücher und ein Heft.","Mi chiamo David e vivo con mia madre in una casa. La mia stanza è sopra, accanto al bagno. Non è grande. A sinistra c’è il mio letto. A destra c’è un tavolo con un computer. Sul tavolo ci sono tre libri e un quaderno."],["Am Fenster steht eine grüne Pflanze. Jeden Morgen mache ich das Fenster auf. Ich höre die Vögel im Garten. Abends lese ich oder telefoniere mit Freunden. Mein Zimmer ist ruhig. Ich bin gern hier.","Vicino alla finestra c’è una pianta verde. Ogni mattina apro la finestra. Sento gli uccelli nel giardino. La sera leggo o telefono agli amici. La mia stanza è tranquilla. Mi piace stare qui."],["Unter meinem Bett liegt eine Tasche mit Sportsachen. An der Tür hängt meine blaue Jacke. Am Samstag räume ich mein Zimmer auf. Ich putze den Tisch und den Boden. Danach treffe ich meine Freunde.","Sotto il mio letto c’è una borsa con le cose per lo sport. Alla porta è appesa la mia giacca blu. Il sabato metto in ordine la stanza. Pulisco il tavolo e il pavimento. Poi incontro i miei amici."]]},{"id":"R3-A1-007","level":"A1","title":"In der Bibliothek","genre":"conversazione breve","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Tina geht am Dienstag in die Bibliothek. Sie sucht ein Buch für Kinder. An der Information sitzt ein Mann. Tina fragt: Wo sind die Kinderbücher? Der Mann zeigt nach links. Dort stehen viele Bücher. Tina findet ein Buch über Tiere.","Tina va martedì in biblioteca. Cerca un libro per bambini. All’ufficio informazioni c’è un uomo. Tina chiede: Dove sono i libri per bambini? L’uomo indica a sinistra. Lì ci sono molti libri. Tina trova un libro sugli animali."],["Sie geht wieder zur Information. Tina: Kann ich das Buch heute mitnehmen? Mann: Ja. Haben Sie eine Karte? Tina: Ja, hier ist sie. Mann: Danke. Bitte bringen Sie das Buch in zwei Wochen zurück. Tina: Das mache ich. Auf Wiedersehen!","Torna all’ufficio informazioni. Tina: Posso portare via il libro oggi? Uomo: Sì. Ha una tessera? Tina: Sì, eccola. Uomo: Grazie. Per favore riporti il libro tra due settimane. Tina: Lo farò. Arrivederci!"],["Die Bibliothek ist jeden Tag geöffnet, aber am Sonntag ist sie geschlossen. Neben dem Eingang stehen zwei Tische. Dort können Kinder lesen. Tina setzt sich kurz hin. Sie liest die erste Seite ihres neuen Buches.","La biblioteca è aperta ogni giorno, ma la domenica è chiusa. Accanto all’ingresso ci sono due tavoli. Lì i bambini possono leggere. Tina si siede un momento. Legge la prima pagina del suo nuovo libro."]]},{"id":"R3-A1-008","level":"A1","title":"Ein einfacher Wochenplan","genre":"programma settimanale","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Montag: Ich arbeite von acht bis vier Uhr. Dienstag: Am Abend lerne ich Deutsch. Mittwoch: Ich kaufe im Supermarkt ein. Donnerstag: Meine Tochter hat Sport. Freitag: Ich koche mit meiner Familie. Samstag: Wir besuchen meine Eltern.","Lunedì: lavoro dalle otto alle quattro. Martedì: la sera studio tedesco. Mercoledì: faccio la spesa al supermercato. Giovedì: mia figlia fa sport. Venerdì: cucino con la mia famiglia. Sabato: andiamo a trovare i miei genitori."],["Sonntag: Wir bleiben zu Hause. Am Morgen frühstücken wir lange. Danach gehen wir in den Park. Wenn es regnet, spielen wir Karten. Ich mag den Sonntag, denn ich habe viel Zeit für meine Familie.","Domenica: restiamo a casa. Al mattino facciamo colazione con calma. Dopo andiamo al parco. Se piove, giochiamo a carte. Mi piace la domenica perché ho molto tempo per la mia famiglia."],["In meiner Küche hängt ein großer Kalender. Ich schreibe jeden Termin auf. Am Montag kaufe ich Blumen. Am Mittwoch rufe ich meinen Bruder an. Meine Tochter malt jeden Sonntag ein kleines Bild in den Kalender.","Nella mia cucina è appeso un grande calendario. Scrivo ogni appuntamento. Lunedì compro fiori. Mercoledì telefono a mio fratello. Mia figlia disegna ogni domenica un piccolo disegno sul calendario."]]},{"id":"R3-A2-001","level":"A2","title":"Ein gebrauchtes Fahrrad","genre":"racconto personale","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Am Wochenende habe ich im Internet ein gebrauchtes Fahrrad gefunden. Die Anzeige war interessant, weil das Fahrrad fast neu aussah. Ich habe dem Verkäufer eine Nachricht geschrieben und wir haben einen Termin für Samstag vereinbart.","Nel fine settimana ho trovato su Internet una bicicletta usata. L’annuncio era interessante perché la bicicletta sembrava quasi nuova. Ho scritto un messaggio al venditore e abbiamo concordato un appuntamento per sabato."],["Als ich ankam, zeigte er mir die Bremsen und die Schaltung. Ich durfte eine kurze Runde fahren. Das Fahrrad fuhr gut, aber das Licht war kaputt. Deshalb haben wir über den Preis gesprochen. Am Ende bezahlte ich achtzig Euro statt hundert. Morgen kaufe ich ein neues Licht.","Quando sono arrivato, mi ha mostrato i freni e il cambio. Ho potuto fare un breve giro. La bicicletta andava bene, ma la luce era rotta. Per questo abbiamo parlato del prezzo. Alla fine ho pagato ottanta euro invece di cento. Domani comprerò una luce nuova."],["Meine Schwester hat das Fahrrad am Sonntag gesehen. Sie möchte jetzt auch eines kaufen. Wir haben zusammen im Internet gesucht und mehrere Anzeigen gefunden. Am nächsten Wochenende wollen wir zwei Verkäufer besuchen.","Mia sorella ha visto la bicicletta domenica. Ora vuole comprarne una anche lei. Abbiamo cercato insieme su Internet e trovato diversi annunci. Il prossimo fine settimana vogliamo visitare due venditori."]]},{"id":"R3-A2-002","level":"A2","title":"Eine E-Mail an die Vermieterin","genre":"email formale semplice","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Sehr geehrte Frau Braun, seit Montag funktioniert die Heizung in unserem Schlafzimmer nicht richtig. Am Morgen ist es dort sehr kalt, obwohl die anderen Zimmer warm sind. Wir haben schon die Bedienungsanleitung gelesen, aber das Problem bleibt.","Gentile signora Braun, da lunedì il riscaldamento nella nostra camera da letto non funziona bene. Al mattino lì fa molto freddo, anche se le altre stanze sono calde. Abbiamo già letto le istruzioni, ma il problema rimane."],["Könnten Sie bitte einen Handwerker schicken? Am Mittwoch bin ich ab vierzehn Uhr zu Hause. Am Donnerstag kann meine Partnerin den ganzen Vormittag warten. Bitte sagen Sie uns, welcher Termin möglich ist. Vielen Dank für Ihre Hilfe. Mit freundlichen Grüßen, Marco Rossi.","Potrebbe mandare un tecnico, per favore? Mercoledì sono a casa dalle quattordici. Giovedì la mia compagna può aspettare tutta la mattina. Per favore ci dica quale appuntamento è possibile. Grazie mille per il suo aiuto. Cordiali saluti, Marco Rossi."],["Wenn Sie weitere Informationen benötigen, können Sie mich unter der angegebenen Telefonnummer erreichen. Am Wochenende sind wir nicht in der Wohnung. Wir hoffen, dass die Reparatur bald möglich ist.","Se ha bisogno di altre informazioni, può raggiungermi al numero di telefono indicato. Nel fine settimana non saremo nell’appartamento. Speriamo che la riparazione sia possibile presto."]]},{"id":"R3-A2-003","level":"A2","title":"Die erste Probe im Musikverein","genre":"piccolo racconto","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Miriam spielt seit zwei Jahren Gitarre. Früher hat sie immer allein geübt. Vor einer Woche hat sie einen Musikverein in ihrer Stadt entdeckt. Sie wollte mit anderen Menschen spielen, war aber vor der ersten Probe sehr nervös.","Miriam suona la chitarra da due anni. Prima si esercitava sempre da sola. Una settimana fa ha scoperto un’associazione musicale nella sua città. Voleva suonare con altre persone, ma era molto nervosa prima della prima prova."],["Im Proberaum begrüßten sie vier Musiker. Zuerst spielte die Gruppe ein einfaches Lied. Danach zeigte Miriam eine Melodie, die sie zu Hause geschrieben hatte. Die anderen fanden die Idee gut und machten Vorschläge. Am Ende der Probe war sie müde, aber glücklich. Nächsten Donnerstag kommt sie wieder.","Nella sala prove l’hanno salutata quattro musicisti. Per prima cosa il gruppo ha suonato una canzone semplice. Dopo Miriam ha mostrato una melodia che aveva scritto a casa. Gli altri hanno trovato buona l’idea e hanno fatto delle proposte. Alla fine della prova era stanca, ma felice. Giovedì prossimo tornerà."],["Zu Hause erzählte sie ihrer Freundin von den netten Musikern. Gemeinsam hörten sie noch einmal die Aufnahme von der Probe. Miriam bemerkte einige Fehler, aber sie war stolz auf ihren ersten Auftritt in der Gruppe.","A casa ha raccontato alla sua amica dei musicisti gentili. Insieme hanno ascoltato ancora una volta la registrazione della prova. Miriam ha notato alcuni errori, ma era orgogliosa della sua prima esibizione nel gruppo."]]},{"id":"R3-A2-004","level":"A2","title":"Ein Ausflug ohne Auto","genre":"resoconto di viaggio","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Unsere Familie wollte am Sonntag einen kleinen Ausflug machen. Weil das Auto in der Werkstatt war, haben wir den Zug genommen. Wir sind früh aufgestanden und haben Brote für das Mittagessen vorbereitet. Am Bahnhof mussten wir nur zehn Minuten warten.","La nostra famiglia voleva fare una piccola gita domenica. Siccome l’auto era in officina, abbiamo preso il treno. Ci siamo alzati presto e abbiamo preparato dei panini per pranzo. Alla stazione abbiamo dovuto aspettare solo dieci minuti."],["Im Dorf sind wir zu einem See gelaufen. Die Kinder haben Enten beobachtet und viele Fotos gemacht. Später wurde es windig, deshalb gingen wir in ein kleines Café. Dort tranken wir etwas Warmes. Abends kamen wir mit dem Zug zurück. Der Tag war schön, obwohl wir viel gelaufen sind.","Nel paese siamo andati a piedi fino a un lago. I bambini hanno osservato le anatre e scattato molte foto. Più tardi si è alzato il vento, quindi siamo entrati in un piccolo bar. Lì abbiamo bevuto qualcosa di caldo. La sera siamo tornati in treno. È stata una bella giornata, anche se abbiamo camminato molto."],["Die Kinder waren besonders begeistert, weil sie auf der Rückfahrt am Fenster sitzen durften. Sie erzählten von den Enten und den großen Bäumen. Zu Hause planten sie schon den nächsten Ausflug.","I bambini erano particolarmente entusiasti perché durante il ritorno hanno potuto sedersi vicino al finestrino. Hanno raccontato delle anatre e degli alberi grandi. A casa hanno già programmato la prossima gita."]]},{"id":"R3-A2-005","level":"A2","title":"Der verlorene Schlüssel","genre":"storia quotidiana","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Nach der Arbeit wollte Sven seine Wohnung aufschließen, aber sein Schlüssel war nicht in der Tasche. Zuerst suchte er in seinem Rucksack. Dann erinnerte er sich, dass er am Morgen beim Bäcker gewesen war. Vielleicht hatte er den Schlüssel dort liegen lassen.","Dopo il lavoro Sven voleva aprire il suo appartamento, ma la chiave non era nella tasca. Prima ha cercato nello zaino. Poi si è ricordato che al mattino era stato dal panettiere. Forse aveva lasciato la chiave lì."],["Er rief die Bäckerei an. Eine Mitarbeiterin hatte tatsächlich einen Schlüssel gefunden. Sven fuhr sofort dorthin und beschrieb seinen Schlüsselanhänger. Alles passte. Die Verkäuferin gab ihm die Schlüssel zurück. Er bedankte sich und kaufte ein Brot. Zu Hause legte er die Schlüssel an einen festen Platz.","Ha telefonato al panificio. Una dipendente aveva effettivamente trovato una chiave. Sven è andato subito lì e ha descritto il suo portachiavi. Tutto corrispondeva. La commessa gli ha restituito le chiavi. Lui l’ha ringraziata e ha comprato un pane. A casa ha messo le chiavi in un posto fisso."],["Am nächsten Tag erzählte Sven seiner Kollegin die Geschichte. Sie lachte und sagte, dass sie deshalb immer einen zweiten Schlüssel bei ihrer Schwester hat. Sven fand die Idee gut und wollte es genauso machen.","Il giorno dopo Sven ha raccontato la storia alla collega. Lei ha riso e ha detto che per questo tiene sempre una seconda chiave da sua sorella. Sven ha trovato buona l’idea e voleva fare lo stesso."]]},{"id":"R3-A2-006","level":"A2","title":"Neues Angebot im Sportverein","genre":"annuncio informativo","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Unser Sportverein bietet ab September einen neuen Kurs für Erwachsene an. Der Kurs heißt „Bewegung nach der Arbeit“ und findet jeden Dienstag von achtzehn bis neunzehn Uhr statt. Sie brauchen keine besonderen Kenntnisse. Bequeme Kleidung und eine Wasserflasche reichen aus.","La nostra associazione sportiva offre da settembre un nuovo corso per adulti. Il corso si chiama «Movimento dopo il lavoro» e si tiene ogni martedì dalle diciotto alle diciannove. Non servono conoscenze particolari. Bastano vestiti comodi e una bottiglia d’acqua."],["In der ersten Stunde lernen Sie die Trainerin kennen. Danach können Sie entscheiden, ob Sie weitermachen möchten. Mitglieder bezahlen zehn Euro im Monat, andere Personen fünfzehn Euro. Bitte melden Sie sich spätestens eine Woche vor Kursbeginn per E-Mail an. Wir freuen uns über neue Teilnehmerinnen und Teilnehmer.","Nella prima lezione conoscerete l’allenatrice. Poi potrete decidere se volete continuare. I soci pagano dieci euro al mese, le altre persone quindici. Per favore iscrivetevi via email al più tardi una settimana prima dell’inizio del corso. Saremo felici di accogliere nuovi partecipanti."],["Nach dem Unterricht können Sie mit anderen Teilnehmern sprechen und gemeinsam Übungen wiederholen. Die Trainerin beantwortet gerne Fragen. Wer regelmäßig kommt, bekommt am Ende des Jahres eine kleine Teilnahmebestätigung.","Dopo la lezione potete parlare con gli altri partecipanti e ripetere insieme gli esercizi. L’allenatrice risponde volentieri alle domande. Chi frequenta regolarmente riceve alla fine dell’anno un piccolo attestato di partecipazione."]]},{"id":"R3-A2-007","level":"A2","title":"Meine Kollegin zieht um","genre":"chat fra colleghi","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Nora: Hallo Paul, kannst du mir am Samstag helfen? Ich ziehe in eine neue Wohnung und muss einige Kartons tragen. Paul: Natürlich! Wann soll ich kommen? Nora: Gegen neun Uhr. Der Transporter kommt um halb zehn. Paul: Brauchst du auch Werkzeug?","Nora: Ciao Paul, puoi aiutarmi sabato? Mi trasferisco in un nuovo appartamento e devo trasportare alcuni scatoloni. Paul: Certamente! Quando devo venire? Nora: Verso le nove. Il furgone arriva alle nove e mezza. Paul: Hai bisogno anche di attrezzi?"],["Nora: Ja, bitte bring deinen Schraubenzieher mit. Wir müssen das Bett auseinanderbauen. Nach dem Umzug lade ich alle Helfer zum Essen ein. Paul: Gute Idee. Ich komme mit dem Fahrrad und bringe die Werkzeuge. Nora: Vielen Dank! Wir sehen uns am Samstag.","Nora: Sì, per favore porta il tuo cacciavite. Dobbiamo smontare il letto. Dopo il trasloco invito tutti quelli che aiutano a mangiare. Paul: Buona idea. Vengo in bicicletta e porto gli attrezzi. Nora: Grazie mille! Ci vediamo sabato."],["Am Montag nach dem Umzug bedankte sich Nora im Büro noch einmal bei allen. Sie zeigte Bilder vom neuen Wohnzimmer. Das Bett stand schon am richtigen Platz, aber die Küche war noch nicht fertig.","Il lunedì dopo il trasloco Nora ha ringraziato ancora tutti in ufficio. Ha mostrato foto del nuovo soggiorno. Il letto era già al posto giusto, ma la cucina non era ancora pronta."]]},{"id":"R3-A2-008","level":"A2","title":"Die Pflanzen auf dem Balkon","genre":"esperienza personale","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Letzten Frühling habe ich zum ersten Mal Gemüse auf meinem Balkon gepflanzt. Meine Nachbarin hat mir gezeigt, wie man Tomaten und Salat in großen Töpfen anbaut. Zuerst musste ich Erde kaufen und einen Platz mit viel Sonne finden.","La primavera scorsa ho piantato per la prima volta verdure sul mio balcone. La mia vicina mi ha mostrato come coltivare pomodori e insalata in grandi vasi. Per prima cosa ho dovuto comprare della terra e trovare un posto con molto sole."],["An warmen Tagen musste ich jeden Abend gießen. Einmal habe ich es vergessen und einige Blätter wurden trocken. Danach habe ich einen Plan gemacht. Im Juli konnte ich die ersten Tomaten essen. Sie waren klein, aber sehr lecker. Dieses Jahr möchte ich auch Kräuter pflanzen.","Nei giorni caldi dovevo annaffiare ogni sera. Una volta me ne sono dimenticato e alcune foglie si sono seccate. Dopo ho preparato un programma. A luglio ho potuto mangiare i primi pomodori. Erano piccoli, ma molto buoni. Quest’anno vorrei piantare anche delle erbe aromatiche."],["Außerdem möchte ich eine kleine Kiste für meine Gartengeräte bauen. So liegen die Sachen nicht überall auf dem Balkon. Meine Nachbarin hat mir versprochen, mich auch in diesem Jahr zu beraten.","Inoltre vorrei costruire una piccola cassa per gli attrezzi da giardino. Così le cose non saranno sparse sul balcone. La vicina mi ha promesso di consigliarmi anche quest’anno."]]},{"id":"R3-B1-001","level":"B1","title":"Ein Vorstellungsgespräch in der Werkstatt","genre":"colloquio di lavoro","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Als Daniel die Einladung zum Vorstellungsgespräch erhielt, war er erleichtert. Seit mehreren Wochen suchte er eine neue Stelle. Er hatte früher in einer kleinen Werkstatt gearbeitet und dort Maschinen bedient. Nun wollte er seine Kenntnisse in einem größeren Betrieb einsetzen. Vor dem Termin las er noch einmal die Stellenanzeige und bereitete Fragen zur Einarbeitung vor.","Quando Daniel ha ricevuto l’invito a un colloquio, si è sentito sollevato. Cercava un nuovo posto da diverse settimane. In passato aveva lavorato in una piccola officina, dove utilizzava macchinari. Ora voleva mettere a frutto le sue competenze in un’azienda più grande. Prima dell’appuntamento ha riletto l’annuncio e preparato domande sulla formazione iniziale."],["Die Personalchefin fragte nicht nur nach seinen technischen Fähigkeiten. Sie wollte auch wissen, wie er mit Fehlern umging. Daniel erzählte von einem Problem an einer Maschine, das er gemeinsam mit einem Kollegen gelöst hatte. Als er selbst Fragen stellen durfte, erkundigte er sich nach den Arbeitszeiten und nach Weiterbildungsmöglichkeiten. Eine Zusage bekam er noch nicht, doch das Gespräch verlief freundlich und klar.","La responsabile del personale non gli ha chiesto soltanto delle capacità tecniche. Voleva anche sapere come affrontasse gli errori. Daniel ha raccontato di un problema a una macchina che aveva risolto insieme a un collega. Quando ha potuto fare domande, si è informato sugli orari e sulle possibilità di formazione. Non ha ancora ricevuto una conferma, ma il colloquio si è svolto in modo cordiale e chiaro."]]},{"id":"R3-B1-002","level":"B1","title":"Ein Brief von der Schule","genre":"comunicazione scolastica","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Liebe Eltern, in den letzten Wochen haben wir beobachtet, dass einige Kinder in den Pausen häufiger streiten. Deshalb möchten wir mit den Klassen darüber sprechen, wie man Probleme lösen kann, ohne andere zu beleidigen. Jedes Kind soll seine Meinung sagen dürfen, aber niemand muss persönliche Erlebnisse vor der ganzen Klasse erzählen.","Cari genitori, nelle ultime settimane abbiamo osservato che alcuni bambini litigano più spesso durante la ricreazione. Per questo vorremmo parlare con le classi di come risolvere i problemi senza insultare gli altri. Ogni bambino deve poter esprimere la propria opinione, ma nessuno è obbligato a raccontare esperienze personali davanti a tutta la classe."],["Am Donnerstag bieten wir einen Elternabend an, bei dem wir unser neues Projekt vorstellen. Eine Schulsozialarbeiterin wird erklären, wie Kinder Unterstützung bekommen können. Wenn Sie an diesem Abend verhindert sind, können Sie uns gerne schriftlich Fragen schicken. Uns ist wichtig, dass Schule und Eltern zusammenarbeiten und die Kinder sich im Unterricht und in der Freizeit sicher fühlen.","Giovedì organizziamo una serata per i genitori durante la quale presenteremo il nuovo progetto. Un’assistente sociale scolastica spiegherà come i bambini possono ricevere sostegno. Se quella sera non potete partecipare, potete inviarci le vostre domande per iscritto. Per noi è importante che scuola e famiglie collaborino e che i bambini si sentano al sicuro durante le lezioni e nel tempo libero."]]},{"id":"R3-B1-003","level":"B1","title":"Eine unerwartete Rechnung","genre":"racconto e reclamo","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Vor drei Monaten bestellte Lara im Internet einen neuen Staubsauger. Der Preis war günstig und die Lieferung kam pünktlich. Jetzt erhielt sie jedoch eine Rechnung für einen zusätzlichen Service, den sie ihrer Meinung nach nie bestellt hatte. Zuerst vermutete sie einen Fehler und suchte die Bestellbestätigung in ihren E-Mails.","Tre mesi fa Lara ha ordinato su Internet un nuovo aspirapolvere. Il prezzo era conveniente e la consegna è arrivata puntuale. Ora però ha ricevuto una fattura per un servizio aggiuntivo che, secondo lei, non aveva mai richiesto. All’inizio ha pensato a un errore e ha cercato la conferma dell’ordine nelle sue email."],["Dort stand tatsächlich etwas über ein kostenpflichtiges Angebot, allerdings nur in einem schwer verständlichen Abschnitt. Lara schrieb dem Kundendienst, dass sie keine bewusste Zustimmung gegeben habe, und bat um eine Erklärung. Sie schickte die Bestellunterlagen mit und setzte eine Frist für die Antwort. Einige Tage später entschuldigte sich das Unternehmen und stornierte die Rechnung. Lara beschloss, bei künftigen Bestellungen die Bedingungen genauer zu lesen.","Lì era effettivamente indicata un’offerta a pagamento, ma soltanto in una sezione difficile da comprendere. Lara ha scritto all’assistenza clienti spiegando che non aveva dato un consenso consapevole e chiedendo chiarimenti. Ha allegato i documenti dell’ordine e indicato un termine per la risposta. Qualche giorno dopo l’azienda si è scusata e ha annullato la fattura. Lara ha deciso che in futuro leggerà con più attenzione le condizioni di acquisto."]]},{"id":"R3-B1-004","level":"B1","title":"Das neue Gemeinschaftsprojekt","genre":"articolo di quartiere","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["In einem Stadtviertel stand viele Jahre lang ein kleines Grundstück leer. Im Sommer beschlossen mehrere Nachbarn, daraus einen Gemeinschaftsgarten zu machen. Sie fragten bei der Stadt nach, wer Eigentümer des Grundstücks war, und erhielten schließlich eine Erlaubnis für die Nutzung. Danach sammelten sie Werkzeuge, bauten Beete und besprachen Regeln für die Zusammenarbeit.","In un quartiere un piccolo terreno è rimasto vuoto per molti anni. In estate alcuni vicini hanno deciso di trasformarlo in un orto comunitario. Si sono informati presso il comune su chi fosse il proprietario del terreno e alla fine hanno ottenuto il permesso di utilizzarlo. Poi hanno raccolto attrezzi, costruito aiuole e discusso regole per la collaborazione."],["Nicht alles funktionierte sofort. Einige Menschen wollten Blumen pflanzen, andere bevorzugten Gemüse. Außerdem musste geklärt werden, wer sich während der Ferien um das Gießen kümmert. Bei einem Treffen fanden die Beteiligten einen Kompromiss. Heute kommen dort Familien, Jugendliche und ältere Menschen zusammen. Der Garten produziert noch nicht besonders viel, doch er hat bereits neue Kontakte zwischen Menschen geschaffen, die sich vorher kaum kannten.","Non tutto ha funzionato subito. Alcune persone volevano piantare fiori, altre preferivano ortaggi. Inoltre bisognava chiarire chi si sarebbe occupato dell’irrigazione durante le vacanze. Durante una riunione i partecipanti hanno trovato un compromesso. Oggi lì si incontrano famiglie, giovani e persone anziane. L’orto non produce ancora molto, ma ha già creato nuovi rapporti tra persone che prima si conoscevano appena."]]},{"id":"R3-B1-005","level":"B1","title":"Warum ich einen Beruf wechseln möchte","genre":"articolo personale","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Ich habe lange als Verkäufer gearbeitet und viele interessante Menschen kennengelernt. Besonders gefallen hat mir, wenn ich Kunden bei einer schwierigen Entscheidung helfen konnte. In den letzten Jahren bemerkte ich jedoch, dass ich mich beruflich kaum noch weiterentwickelte. Deshalb begann ich abends einen Kurs für technische Zeichnungen.","Ho lavorato a lungo come commesso e conosciuto molte persone interessanti. Mi piaceva soprattutto quando potevo aiutare i clienti a prendere una decisione difficile. Negli ultimi anni, però, ho notato che professionalmente non facevo quasi più progressi. Per questo ho iniziato a frequentare la sera un corso di disegno tecnico."],["Der Kurs war anstrengender als erwartet, weil ich neben der Arbeit lernen musste. Trotzdem machte ich weiter, und nach sechs Monaten konnte ich mein erstes kleines Projekt zeigen. Jetzt bewerbe ich mich auf Stellen, bei denen ich beides nutzen kann: meine Erfahrung im Umgang mit Menschen und meine neuen technischen Kenntnisse. Ich weiß, dass ein Berufswechsel Zeit braucht, aber ich möchte diese Möglichkeit nicht ungenutzt lassen.","Il corso è stato più impegnativo del previsto perché dovevo studiare oltre a lavorare. Nonostante ciò ho continuato e dopo sei mesi ho potuto mostrare il mio primo piccolo progetto. Ora mi candido per posizioni nelle quali posso usare entrambe le cose: la mia esperienza con le persone e le nuove competenze tecniche. So che cambiare professione richiede tempo, ma non voglio lasciarmi sfuggire questa opportunità."]]},{"id":"R3-B1-006","level":"B1","title":"Verspätung auf dem Weg zum Konzert","genre":"cronaca di un viaggio","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Zwei Freunde wollten am Freitagabend ein Konzert in einer anderen Stadt besuchen. Sie hatten die Tickets schon vor Monaten gekauft und waren früh zum Bahnhof gefahren. Kurz vor der Abfahrt erschien eine Meldung auf der Anzeigetafel: Wegen einer technischen Störung würde der Zug mindestens vierzig Minuten später kommen.","Due amici volevano andare venerdì sera a un concerto in un’altra città. Avevano comprato i biglietti già mesi prima ed erano arrivati presto alla stazione. Poco prima della partenza è apparso un messaggio sul tabellone: a causa di un guasto tecnico il treno sarebbe arrivato con almeno quaranta minuti di ritardo."],["Zuerst ärgerten sie sich, weil sie den Beginn des Konzerts nicht verpassen wollten. Dann suchten sie gemeinsam nach einer anderen Verbindung. Ein Regionalbus fuhr zwar langsamer, hielt aber direkt vor der Konzerthalle. Die Freunde entschieden sich für den Bus und informierten einen Bekannten, der bereits am Eingang wartete. Schließlich erreichten sie die Halle nur zehn Minuten nach Beginn. Beim nächsten Mal wollen sie trotzdem mehr Zeit einplanen.","All’inizio si sono arrabbiati perché non volevano perdere l’inizio del concerto. Poi hanno cercato insieme un collegamento alternativo. Un autobus regionale era più lento, ma fermava proprio davanti alla sala concerti. Gli amici hanno scelto l’autobus e avvisato un conoscente che li aspettava già all’ingresso. Alla fine sono arrivati soltanto dieci minuti dopo l’inizio. La prossima volta vogliono comunque prevedere più tempo."]]},{"id":"R3-B1-007","level":"B1","title":"Ein Kurs für freiwillige Helfer","genre":"annuncio e testimonianza","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Eine gemeinnützige Organisation bietet ab nächstem Monat einen Kurs für Menschen an, die älteren Nachbarn helfen möchten. Die Teilnehmenden lernen, wie sie Gespräche führen, kleine Einkäufe erledigen und bei der Suche nach offiziellen Informationen unterstützen können. Medizinische Aufgaben gehören ausdrücklich nicht dazu. Für den Kurs sind keine Vorkenntnisse nötig.","Un’organizzazione senza scopo di lucro offre dal prossimo mese un corso per chi desidera aiutare i vicini anziani. I partecipanti imparano a conversare, fare piccoli acquisti e sostenere la ricerca di informazioni ufficiali. Le mansioni mediche sono espressamente escluse. Non sono necessarie conoscenze preliminari."],["Martin hat im vergangenen Jahr an einem ähnlichen Projekt teilgenommen. Er besucht heute einmal pro Woche einen Mann, der früher als Lehrer gearbeitet hat. Die beiden sprechen über Bücher und machen bei gutem Wetter Spaziergänge. Martin sagt, dass er nicht nur Zeit schenkt, sondern selbst viel lernt. Wer sich anmelden möchte, kann sich bis Ende des Monats im Bürgerbüro informieren.","Martin ha partecipato l’anno scorso a un progetto simile. Ora visita una volta alla settimana un uomo che in passato lavorava come insegnante. I due parlano di libri e fanno passeggiate quando il tempo è bello. Martin dice che non soltanto dedica il proprio tempo, ma impara anche molto. Chi vuole iscriversi può chiedere informazioni all’ufficio comunale entro la fine del mese."]]},{"id":"R3-B1-008","level":"B1","title":"Die Entscheidung im Sportteam","genre":"racconto su un conflitto","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Vor dem letzten Wettkampf der Saison musste eine Mannschaft entscheiden, wer am Samstag starten sollte. Zwei Mitglieder waren verletzt, und mehrere neue Sportler hatten erst wenig Erfahrung. Der Trainer wollte schnell eine Entscheidung treffen, doch einige Teilnehmer fanden die Auswahl unfair. Deshalb schlug die Kapitänin ein gemeinsames Gespräch vor.","Prima dell’ultima gara della stagione una squadra doveva decidere chi avrebbe partecipato sabato. Due membri erano infortunati e diversi atleti nuovi avevano poca esperienza. L’allenatore voleva decidere in fretta, ma alcuni partecipanti trovavano la selezione ingiusta. Per questo la capitana ha proposto un confronto con tutti."],["Bei dem Treffen erklärte der Trainer, welche Fähigkeiten für den Wettkampf wichtig waren. Anschließend konnten die Spieler Fragen stellen und ihre Wünsche nennen. Am Ende einigten sie sich darauf, dass die erfahrenen Mitglieder teilnehmen und die jüngeren als Ersatz mitfahren. Außerdem wurde eine zusätzliche Trainingsgruppe für Anfänger gegründet. Nicht jeder war vollkommen zufrieden, aber alle verstanden die Gründe für die Entscheidung besser.","Durante l’incontro l’allenatore ha spiegato quali capacità fossero importanti per la gara. In seguito i giocatori hanno potuto fare domande ed esprimere le proprie preferenze. Alla fine hanno concordato che avrebbero partecipato i membri esperti, mentre i più giovani sarebbero andati come riserve. Inoltre è stato creato un gruppo di allenamento aggiuntivo per principianti. Non tutti erano completamente soddisfatti, ma tutti comprendevano meglio le ragioni della decisione."]]},{"id":"R3-B2-001","level":"B2","title":"Wem gehört unser digitales Profil?","genre":"articolo di opinione","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Viele digitale Dienste versprechen, das Leben bequemer zu machen. Navigationsprogramme zeigen den schnellsten Weg, Einkaufsplattformen empfehlen passende Produkte und Gesundheitsanwendungen erinnern an Bewegungspausen. Diese Vorteile entstehen jedoch häufig dadurch, dass Unternehmen große Mengen persönlicher Daten auswerten. Während manche Nutzerinnen und Nutzer den praktischen Nutzen betonen, fragen andere, wie frei eine Entscheidung noch ist, wenn jede Handlung gespeichert wird.","Molti servizi digitali promettono di rendere più comoda la vita. I programmi di navigazione mostrano il percorso più rapido, le piattaforme commerciali consigliano prodotti adatti e le applicazioni per la salute ricordano di fare pause attive. Questi vantaggi, però, spesso nascono dall’analisi di grandi quantità di dati personali. Mentre alcuni utenti sottolineano l’utilità pratica, altri si chiedono quanto sia ancora libera una decisione quando ogni azione viene registrata."],["Besonders schwierig ist die Frage nach der Zustimmung. Wer einen Dienst benötigt, akzeptiert manchmal umfangreiche Bedingungen, ohne sie vollständig zu verstehen. Aus rechtlicher Sicht kann dies wie eine freie Wahl aussehen, tatsächlich fehlen aber oft gleichwertige Alternativen. Deshalb fordern Verbraucherschützer verständliche Einstellungen und klare Grenzen für die Weitergabe von Informationen. Die Herausforderung besteht darin, innovative Anwendungen zu ermöglichen, ohne Menschen zu zwingen, ihre Privatsphäre vollständig aufzugeben.","La questione del consenso è particolarmente difficile. Chi ha bisogno di un servizio talvolta accetta condizioni molto estese senza comprenderle pienamente. Dal punto di vista giuridico può sembrare una scelta libera, ma nella pratica spesso mancano alternative equivalenti. Per questo le associazioni dei consumatori chiedono impostazioni comprensibili e limiti chiari alla condivisione delle informazioni. La sfida consiste nel consentire applicazioni innovative senza costringere le persone a rinunciare completamente alla propria riservatezza."]]},{"id":"R3-B2-002","level":"B2","title":"Eine Stadt plant mehr Schatten","genre":"reportage urbano","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Nach mehreren außergewöhnlich heißen Sommern diskutiert eine Stadtverwaltung darüber, wie öffentliche Plätze verändert werden sollen. Auf einem großen Platz stehen bislang kaum Bäume. Im Sommer erhitzen sich die Steine so stark, dass viele Menschen den Ort am Nachmittag meiden. Ein Planungsbüro schlägt vor, einen Teil der Parkplätze durch Grünflächen, Sitzgelegenheiten und Trinkbrunnen zu ersetzen.","Dopo diverse estati eccezionalmente calde, un’amministrazione comunale discute come modificare gli spazi pubblici. In una grande piazza attualmente ci sono pochissimi alberi. In estate le pietre si scaldano così tanto che molte persone evitano il luogo nel pomeriggio. Uno studio di progettazione propone di sostituire parte dei parcheggi con aree verdi, panchine e fontanelle."],["Der Vorschlag stößt auf unterschiedliche Reaktionen. Geschäftsleute befürchten, Kundschaft zu verlieren, während Anwohner die neue Gestaltung begrüßen. Eine Verkehrsuntersuchung zeigt allerdings, dass viele Besucher bereits mit Bus oder Fahrrad kommen. Die Verwaltung plant deshalb zunächst einen befristeten Versuch: Für sechs Monate werden mobile Bäume aufgestellt und einige Flächen gesperrt. Erst danach soll entschieden werden, ob der Umbau dauerhaft erfolgt. So lassen sich Erwartungen mit tatsächlichen Erfahrungen vergleichen.","La proposta suscita reazioni diverse. I commercianti temono di perdere clienti, mentre i residenti accolgono positivamente la nuova sistemazione. Uno studio sul traffico mostra però che molti visitatori arrivano già con autobus o bicicletta. L’amministrazione prevede quindi prima un esperimento temporaneo: per sei mesi saranno collocati alberi mobili e alcune aree saranno chiuse al traffico. Solo dopo si deciderà se la trasformazione sarà permanente. In questo modo sarà possibile confrontare le aspettative con le esperienze reali."]]},{"id":"R3-B2-003","level":"B2","title":"Ein Museum zeigt vergessene Fotografien","genre":"recensione culturale","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Die neue Ausstellung eines regionalen Museums widmet sich Fotografien, die jahrzehntelang in privaten Schubladen lagen. Die Bilder dokumentieren nicht die großen politischen Ereignisse, sondern gewöhnliche Situationen: Menschen an ihrem Arbeitsplatz, Familienfeiern, Straßenszenen und unauffällige Veränderungen der Architektur. Gerade diese alltäglichen Motive machen den Reiz der Schau aus. Die Besucherinnen und Besucher entdecken, wie sich eine Stadt verändert, ohne dass jemand diese Entwicklung bewusst geplant hätte.","La nuova mostra di un museo regionale è dedicata a fotografie rimaste per decenni nei cassetti privati. Le immagini non documentano i grandi eventi politici, ma situazioni comuni: persone sul posto di lavoro, feste di famiglia, scene di strada e cambiamenti poco appariscenti dell’architettura. Proprio questi soggetti quotidiani rendono interessante l’esposizione. I visitatori scoprono come una città cambi senza che qualcuno abbia pianificato consapevolmente tale sviluppo."],["Bemerkenswert ist, dass das Museum zu jedem Foto mehrere Perspektiven anbietet. Neben historischen Informationen stehen Erinnerungen der ursprünglichen Besitzer, die gelegentlich voneinander abweichen. Statt diese Unterschiede zu verbergen, macht die Ausstellung sie sichtbar. Sie erinnert daran, dass Bilder zwar Einzelheiten festhalten, aber nicht automatisch die ganze Wahrheit zeigen. Eine kritische Auswahl wäre dennoch hilfreich gewesen: Einige Themen werden ausführlich behandelt, während die Lebenswelten von Zugewanderten nur am Rand erscheinen.","È notevole che il museo offra più prospettive per ogni fotografia. Accanto alle informazioni storiche compaiono i ricordi dei proprietari originali, che talvolta divergono. Invece di nascondere queste differenze, la mostra le rende visibili. Ricorda così che le immagini fissano dettagli, ma non mostrano automaticamente tutta la verità. Una selezione più critica sarebbe stata comunque utile: alcuni temi sono trattati diffusamente, mentre le esperienze delle persone immigrate appaiono soltanto marginalmente."]]},{"id":"R3-B2-004","level":"B2","title":"Interview über flexibles Arbeiten","genre":"intervista","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Redaktion: Viele Unternehmen bieten flexible Arbeitszeiten an. Bedeutet das automatisch mehr Freiheit? Expertin: Nicht unbedingt. Wer Beginn und Ende der Arbeit selbst festlegen kann, gewinnt zunächst Handlungsspielraum. Gleichzeitig verschwimmen oft die Grenzen zwischen Berufsleben und Freizeit. Besonders schwierig wird es, wenn Beschäftigte ständig erreichbar sein sollen, obwohl niemand dies ausdrücklich verlangt.","Redazione: Molte aziende offrono orari flessibili. Questo significa automaticamente maggiore libertà? Esperta: Non necessariamente. Chi può decidere da sé quando iniziare e finire il lavoro guadagna inizialmente maggiore autonomia. Allo stesso tempo spesso si confondono i confini tra lavoro e tempo libero. Diventa particolarmente difficile quando i dipendenti sentono di dover essere sempre reperibili, anche se nessuno lo richiede espressamente."],["Redaktion: Welche Regeln könnten helfen? Expertin: Teams sollten vereinbaren, zu welchen Zeiten Antworten erwartet werden und wann niemand reagieren muss. Außerdem braucht es eine realistische Planung der Aufgaben. Sonst wird Flexibilität zur bloßen Verschiebung von Verantwortung. Redaktion: Sind solche Modelle für alle Berufe möglich? Expertin: Nein. In der Pflege, im Einzelhandel oder in der Produktion gelten andere Bedingungen. Dort muss man über Dienstpläne, Tauschmöglichkeiten und faire Belastung sprechen, statt Lösungen aus dem Bürobereich einfach zu übernehmen.","Redazione: Quali regole potrebbero aiutare? Esperta: Le squadre dovrebbero concordare in quali orari ci si aspetta una risposta e quando nessuno è tenuto a reagire. Inoltre serve una pianificazione realistica dei compiti. Altrimenti la flessibilità diventa soltanto uno spostamento delle responsabilità. Redazione: Questi modelli sono possibili in tutte le professioni? Esperta: No. Nell’assistenza sanitaria, nel commercio al dettaglio o nella produzione valgono condizioni diverse. Lì bisogna discutere turni, possibilità di scambio e distribuzione equa del carico, invece di trasferire semplicemente soluzioni pensate per gli uffici."]]},{"id":"R3-B2-005","level":"B2","title":"Soll eine Schule Smartphones verbieten?","genre":"commento argomentativo","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["In vielen Schulen wird darüber gestritten, welche Rolle Smartphones während des Unterrichts und in den Pausen spielen sollten. Befürworter eines Verbots argumentieren, dass ständige Benachrichtigungen die Aufmerksamkeit beeinträchtigen und Konflikte über soziale Netzwerke bis ins Klassenzimmer tragen. Andere weisen darauf hin, dass Jugendliche den verantwortungsvollen Umgang mit digitalen Medien gerade in der Schule lernen müssen. Ein absolutes Verbot könnte diese Aufgabe lediglich auf die Familien verlagern.","In molte scuole si discute su quale ruolo debbano avere gli smartphone durante le lezioni e negli intervalli. I sostenitori di un divieto sostengono che le notifiche continue danneggiano l’attenzione e portano in classe conflitti nati sui social network. Altri fanno notare che i giovani devono imparare proprio a scuola a usare in modo responsabile i mezzi digitali. Un divieto assoluto potrebbe soltanto trasferire questo compito alle famiglie."],["Eine mögliche Lösung besteht darin, klare Phasen zu unterscheiden. Während konzentrierter Arbeitszeiten bleiben die Geräte ausgeschaltet; bei Rechercheaufgaben können sie gezielt eingesetzt werden. Entscheidend ist jedoch nicht allein die technische Regel, sondern ihre nachvollziehbare Begründung. Wenn Lehrkräfte, Schülerinnen, Schüler und Eltern gemeinsam über Grenzen sprechen, entsteht eher Akzeptanz. Die Debatte sollte deshalb weniger um die Geräte selbst kreisen als um die Frage, wie Lernen und Zusammenleben gelingen können.","Una possibile soluzione consiste nel distinguere fasi chiare. Durante le attività che richiedono concentrazione i dispositivi rimangono spenti; nelle ricerche possono invece essere usati in modo mirato. Decisiva, però, non è soltanto la regola tecnica, ma la sua motivazione comprensibile. Se insegnanti, studenti e genitori discutono insieme dei limiti, è più probabile che vengano accettati. Per questo il dibattito dovrebbe concentrarsi meno sui dispositivi e più sulla domanda di come possano funzionare l’apprendimento e la convivenza."]]},{"id":"R3-B2-006","level":"B2","title":"Die zweite Nutzung eines alten Gebäudes","genre":"articolo su architettura","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Eine ehemalige Fabrik soll zu einem öffentlichen Kulturhaus umgebaut werden. Das Gebäude steht seit Jahren leer, besitzt aber große Hallen und eine auffällige Fassade. Die Architekten möchten möglichst viel erhalten, während die Stadt auf niedrige Betriebskosten achtet. Besonders umstritten ist die Frage, ob alte Fenster ersetzt werden müssen, damit der Energieverbrauch sinkt.","Una ex fabbrica deve essere trasformata in un centro culturale pubblico. L’edificio è vuoto da anni, ma possiede grandi capannoni e una facciata particolare. Gli architetti vorrebbero conservare il più possibile, mentre il comune presta attenzione ai bassi costi di gestione. È particolarmente controversa la domanda se le vecchie finestre debbano essere sostituite per ridurre il consumo energetico."],["Bei einer Informationsveranstaltung erklären Fachleute, dass Denkmalschutz und Klimaschutz nicht zwangsläufig Gegensätze sein müssen. Manche historischen Bauteile lassen sich verbessern, ohne ihr Aussehen grundlegend zu verändern. Andere Maßnahmen kosten allerdings mehr als ein vollständiger Ersatz. Die Entscheidung hängt daher nicht nur vom verfügbaren Geld ab, sondern auch davon, welchen Wert eine Stadt ihrer Geschichte beimisst. Ein gut geplanter Umbau könnte zeigen, dass moderne Nutzung und historische Identität zusammenpassen.","Durante un incontro informativo gli esperti spiegano che la tutela dei monumenti e quella del clima non devono necessariamente essere in contrasto. Alcuni elementi storici possono essere migliorati senza modificarne profondamente l’aspetto. Altri interventi, però, costano più di una sostituzione completa. La decisione dipende quindi non soltanto dai fondi disponibili, ma anche dal valore che una città attribuisce alla propria storia. Una trasformazione ben pianificata potrebbe mostrare che uso moderno e identità storica possono convivere."]]},{"id":"R3-C1-001","level":"C1","title":"Die Verantwortung algorithmischer Entscheidungen","genre":"saggio breve","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Wenn öffentliche Einrichtungen Entscheidungen mithilfe statistischer Modelle vorbereiten, stellt sich nicht nur die Frage nach deren technischer Genauigkeit. Ebenso entscheidend ist, ob die Betroffenen nachvollziehen können, auf welcher Grundlage ein Ergebnis zustande kam. Ein System mag im Durchschnitt zuverlässig arbeiten und dennoch bestimmte Gruppen systematisch benachteiligen, sofern seine Ausgangsdaten frühere gesellschaftliche Ungleichheiten widerspiegeln. Aus dieser Perspektive wäre es irreführend, maschinelle Empfehlungen grundsätzlich als neutral zu behandeln.","Quando le istituzioni pubbliche preparano decisioni con l’aiuto di modelli statistici, la questione non riguarda soltanto la loro precisione tecnica. È altrettanto decisivo che le persone interessate possano capire su quali basi si sia giunti a un risultato. Un sistema può funzionare mediamente in modo affidabile e tuttavia svantaggiare sistematicamente determinati gruppi, qualora i dati iniziali riflettano disuguaglianze sociali precedenti. Da questa prospettiva sarebbe fuorviante considerare sempre neutrali le raccomandazioni automatiche."],["Die Verantwortung lässt sich daher nicht an eine Software delegieren. Behörden müssen ihre Kriterien offenlegen, Entscheidungen anfechtbar machen und prüfen, ob menschliche Kontrolle tatsächlich wirksam ist. Dabei genügt es nicht, am Ende eines Verfahrens eine Person unterschreiben zu lassen. Wer eine automatisierte Empfehlung übernimmt, braucht die fachliche Kompetenz und die institutionelle Freiheit, ihr gegebenenfalls zu widersprechen. Erst unter solchen Bedingungen wird die Technik zu einem überprüfbaren Instrument, statt eine schwer durchschaubare Autorität zu bilden.","La responsabilità non può quindi essere delegata a un software. Le autorità devono rendere noti i criteri, consentire di contestare le decisioni e verificare che il controllo umano sia realmente efficace. Non basta far firmare una persona alla fine di una procedura. Chi accetta una raccomandazione automatizzata deve possedere la competenza professionale e la libertà istituzionale necessarie per opporvisi, se opportuno. Solo a queste condizioni la tecnologia diventa uno strumento verificabile anziché un’autorità difficile da comprendere."]]},{"id":"R3-C1-002","level":"C1","title":"Die Sprache der wissenschaftlichen Unsicherheit","genre":"analisi divulgativa","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Wissenschaftliche Aussagen werden in öffentlichen Debatten häufig so behandelt, als müssten sie entweder endgültig bewiesen oder vollständig wertlos sein. Tatsächlich gehört die Angabe von Unsicherheit jedoch zu den grundlegenden Methoden seriöser Forschung. Wenn eine Studie beispielsweise von einer erhöhten Wahrscheinlichkeit spricht, behauptet sie keineswegs, dass ein bestimmtes Ereignis zwangsläufig eintreten werde. Sie beschreibt vielmehr eine Beziehung, die unter bestimmten Voraussetzungen beobachtet wurde und deren Grenzen benannt werden müssen.","Nel dibattito pubblico le affermazioni scientifiche vengono spesso trattate come se dovessero essere definitivamente dimostrate oppure del tutto prive di valore. In realtà indicare l’incertezza appartiene ai metodi fondamentali della ricerca seria. Quando uno studio, per esempio, parla di probabilità aumentata, non sostiene affatto che un certo evento debba necessariamente verificarsi. Descrive invece una relazione osservata in determinate condizioni, di cui devono essere precisati i limiti."],["Für Journalistinnen und Journalisten entsteht daraus eine besondere Aufgabe: Sie sollen Ergebnisse verständlich darstellen, ohne ihre Vorläufigkeit zu verschweigen. Zuspitzungen können Aufmerksamkeit erzeugen, verändern aber gelegentlich die eigentliche Aussage. Wer dagegen nur auf methodische Einschränkungen hinweist, riskiert, den praktischen Erkenntniswert zu verdecken. Eine gelungene Wissenschaftskommunikation muss deshalb zwischen Genauigkeit, Verständlichkeit und gesellschaftlicher Relevanz vermitteln. Dazu gehört auch, offen zu sagen, welche Fragen noch unbeantwortet geblieben sind.","Ne deriva un compito particolare per i giornalisti: presentare i risultati in modo comprensibile senza nasconderne il carattere provvisorio. Le semplificazioni incisive possono attirare attenzione, ma a volte alterano il messaggio originale. Chi invece sottolinea soltanto i limiti metodologici rischia di oscurarne il valore conoscitivo pratico. Una buona comunicazione scientifica deve quindi mediare tra precisione, comprensibilità e rilevanza sociale. Ciò comprende anche dichiarare apertamente quali domande restino senza risposta."]]},{"id":"R3-C1-003","level":"C1","title":"Ein Archiv zwischen Erinnerung und Datenschutz","genre":"commento storico","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Als ein Stadtarchiv beschloss, private Briefe aus dem vergangenen Jahrhundert zu digitalisieren, stieß das Projekt zunächst auf breite Zustimmung. Die Dokumente versprachen neue Einblicke in die Alltagsgeschichte, insbesondere in Lebensbereiche, die in offiziellen Akten kaum vorkommen. Bald zeigte sich jedoch, dass die Sammlung auch sehr persönliche Informationen über Familienkonflikte, Krankheiten und wirtschaftliche Schwierigkeiten enthielt. Obwohl viele Verfasser längst verstorben waren, konnten Nachkommen in den Texten noch immer identifiziert werden.","Quando un archivio cittadino decise di digitalizzare lettere private del secolo scorso, il progetto incontrò inizialmente un ampio consenso. I documenti promettevano nuove prospettive sulla storia quotidiana, soprattutto su aspetti della vita raramente presenti negli atti ufficiali. Ben presto emerse però che la raccolta conteneva anche informazioni molto personali su conflitti familiari, malattie e difficoltà economiche. Sebbene molti autori fossero morti da tempo, i loro discendenti potevano ancora essere identificati nei testi."],["Die Verantwortlichen standen damit vor einem Dilemma. Eine vollständige Veröffentlichung hätte zwar die Forschung erleichtert, zugleich aber das Vertrauen in den verantwortungsvollen Umgang mit persönlichen Zeugnissen gefährdet. Schließlich entwickelte das Archiv ein abgestuftes Verfahren: Bestimmte Dokumente wurden frei zugänglich gemacht, andere konnten nur nach einer begründeten Anfrage eingesehen werden. Der Fall verdeutlicht, dass historisches Wissen nicht allein eine Frage des Sammelns ist. Ebenso wichtig ist die Entscheidung darüber, unter welchen Bedingungen Erinnerungen öffentlich werden dürfen.","I responsabili si trovarono così davanti a un dilemma. Una pubblicazione completa avrebbe facilitato la ricerca, ma avrebbe anche potuto compromettere la fiducia nella gestione responsabile delle testimonianze personali. Alla fine l’archivio sviluppò una procedura graduata: alcuni documenti furono resi liberamente accessibili, altri consultabili soltanto dopo una richiesta motivata. Il caso mostra che la conoscenza storica non riguarda soltanto la raccolta di materiali. Altrettanto importante è decidere a quali condizioni i ricordi possano diventare pubblici."]]},{"id":"R3-C1-004","level":"C1","title":"Mehrsprachigkeit als gesellschaftliche Ressource","genre":"articolo linguistico","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Mehrsprachigkeit wird im öffentlichen Diskurs widersprüchlich bewertet. Während Fremdsprachenkenntnisse als wirtschaftlicher Vorteil gelten, werden die Sprachen zugewanderter Familien mitunter vor allem unter dem Gesichtspunkt möglicher Integrationsprobleme diskutiert. Diese Unterscheidung sagt weniger über die sprachlichen Fähigkeiten der Sprecherinnen und Sprecher aus als über gesellschaftliche Erwartungen und Machtverhältnisse. Ein Kind, das zwischen mehreren Sprachen wechselt, verfügt keineswegs über ein grundsätzlich defizitäres Sprachsystem.","Il plurilinguismo viene valutato in modo contraddittorio nel dibattito pubblico. Mentre conoscere lingue straniere è considerato un vantaggio economico, le lingue delle famiglie immigrate vengono talvolta discusse soprattutto in relazione a possibili problemi di integrazione. Questa distinzione dice meno sulle capacità linguistiche dei parlanti che sulle aspettative e sui rapporti di potere nella società. Un bambino che passa da una lingua all’altra non possiede affatto un sistema linguistico intrinsecamente deficitario."],["Gleichzeitig wäre es ebenso vereinfachend, die Herausforderungen mehrsprachiger Bildung zu leugnen. Lehrkräfte benötigen geeignete Materialien und Zeit, um unterschiedliche Lernstände zu berücksichtigen. Entscheidend ist deshalb nicht, ob eine Familiensprache im schulischen Alltag sichtbar sein darf, sondern wie sprachliche Ressourcen beim Erwerb zusätzlicher Kenntnisse genutzt werden können. Eine langfristige Bildungspolitik sollte sowohl die gemeinsame Unterrichtssprache stärken als auch vermeiden, dass andere Sprachen pauschal als Hindernis erscheinen.","Allo stesso tempo sarebbe altrettanto semplicistico negare le sfide dell’istruzione plurilingue. Gli insegnanti hanno bisogno di materiali adeguati e tempo per considerare livelli di apprendimento diversi. La questione decisiva non è dunque se una lingua familiare possa essere visibile nella vita scolastica, ma come usare le risorse linguistiche nell’acquisizione di nuove conoscenze. Una politica educativa di lungo periodo dovrebbe rafforzare la lingua comune dell’insegnamento senza far apparire indiscriminatamente le altre lingue come un ostacolo."]]},{"id":"R3-C1-005","level":"C1","title":"Wirtschaftlicher Wert und gesellschaftlicher Nutzen","genre":"editoriale","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["In politischen Diskussionen wird der Erfolg eines Projekts häufig anhand leicht messbarer Kennzahlen beurteilt. Besonders beliebt sind finanzielle Erträge, Besucherzahlen oder die Zahl neu geschaffener Arbeitsplätze. Solche Größen ermöglichen Vergleiche und sind für öffentliche Entscheidungen unverzichtbar. Dennoch bildet ihre Genauigkeit nicht automatisch die gesamte Wirkung eines Vorhabens ab. Ein Kulturzentrum kann beispielsweise wirtschaftlich bescheiden erscheinen und zugleich das Zusammenleben in einem Stadtteil nachhaltig verändern.","Nei dibattiti politici il successo di un progetto viene spesso giudicato attraverso indicatori facili da misurare. Sono particolarmente apprezzati i ricavi finanziari, il numero di visitatori o i posti di lavoro creati. Questi dati permettono confronti e sono indispensabili per le decisioni pubbliche. Tuttavia la loro precisione non rappresenta automaticamente l’intero impatto di un’iniziativa. Un centro culturale, per esempio, può apparire modesto sul piano economico e allo stesso tempo cambiare in modo duraturo la convivenza in un quartiere."],["Daraus folgt allerdings nicht, dass jeder schwer messbare Vorteil eine unbegrenzte Finanzierung rechtfertigt. Vielmehr braucht es transparente Kriterien, die materielle und immaterielle Ergebnisse miteinander verbinden. Besonders aufschlussreich sind langfristige Untersuchungen, die nicht nur unmittelbare Effekte erfassen, sondern auch fragen, wer von einer Maßnahme profitiert und wer möglicherweise ausgeschlossen bleibt. Eine öffentliche Bewertung wird erst dann überzeugend, wenn sie sowohl die Grenzen ihrer Zahlen als auch die Wertentscheidungen hinter ihnen offenlegt.","Da ciò non consegue però che ogni vantaggio difficile da misurare giustifichi un finanziamento illimitato. Servono piuttosto criteri trasparenti che colleghino risultati materiali e immateriali. Sono particolarmente illuminanti gli studi a lungo termine, che non registrano soltanto effetti immediati, ma si chiedono anche chi tragga beneficio da una misura e chi possa rimanerne escluso. Una valutazione pubblica diventa convincente soltanto quando rende espliciti sia i limiti dei propri numeri sia le scelte di valore che vi stanno dietro."]]},{"id":"R3-C1-006","level":"C1","title":"Die Grenzen einer literarischen Interpretation","genre":"saggio di critica letteraria","sourceType":"original","sourceUrl":"","sourceName":"Testo originale per Deutsch Trainer","period":"contemporaneo","pairs":[["Eine literarische Figur wird nicht allein durch das beschrieben, was sie ausdrücklich sagt. Ebenso bedeutsam sind Auslassungen, Widersprüche und die Perspektive, aus der eine Szene erzählt wird. Gerade unzuverlässige Erzähler führen vor Augen, wie sehr eine scheinbar klare Handlung von der Auswahl und Reihenfolge der Informationen abhängt. Wer jede Äußerung unmittelbar als Meinung des Autors deutet, verwechselt daher die Konstruktion eines Textes mit der Haltung der Person, die ihn geschrieben hat.","Un personaggio letterario non è definito soltanto da ciò che dice esplicitamente. Sono altrettanto importanti omissioni, contraddizioni e la prospettiva dalla quale viene narrata una scena. Proprio i narratori inaffidabili mostrano quanto un’azione apparentemente chiara dipenda dalla selezione e dall’ordine delle informazioni. Chi interpreta ogni affermazione direttamente come opinione dell’autore confonde quindi la costruzione del testo con l’atteggiamento della persona che l’ha scritto."],["Gleichzeitig lässt sich eine Interpretation nicht beliebig von den sprachlichen Einzelheiten lösen. Ihre Plausibilität entsteht im Zusammenspiel von Textbelegen, historischem Kontext und nachvollziehbarer Argumentation. Unterschiedliche Lesarten können nebeneinander bestehen, sofern sie die Widerstände des Textes ernst nehmen. Literaturwissenschaftliche Genauigkeit bedeutet somit weder die Suche nach einer einzigen endgültigen Bedeutung noch die Behauptung, jede Deutung sei gleichermaßen gültig. Sie besteht vielmehr darin, begründet zu zeigen, weshalb ein Text bestimmte Möglichkeiten eröffnet und andere ausschließt.","Allo stesso tempo un’interpretazione non può separarsi arbitrariamente dai dettagli linguistici. La sua plausibilità nasce dall’interazione tra prove testuali, contesto storico e argomentazione comprensibile. Letture diverse possono coesistere, purché prendano sul serio le resistenze del testo. Il rigore critico non significa quindi cercare un unico significato definitivo né sostenere che ogni interpretazione sia ugualmente valida. Consiste piuttosto nel mostrare con argomenti perché un testo apra determinate possibilità e ne escluda altre."]]},{"id":"R3-C2-001","level":"C2","title":"Die Verwandlung — Ein ungewöhnliches Erwachen","genre":"estratto letterario autentico","sourceType":"public_domain","sourceUrl":"https://de.wikisource.org/wiki/Die_Verwandlung_(Franz_Kafka)","sourceName":"Franz Kafka, Die Verwandlung (1915)","period":"1915","pairs":[["Als Gregor Samsa eines Morgens aus unruhigen Träumen erwachte, fand er sich in seinem Bett zu einem ungeheueren Ungeziefer verwandelt. Er lag auf seinem panzerartig harten Rücken und sah, wenn er den Kopf ein wenig hob, seinen gewölbten, braunen, von bogenförmigen Versteifungen geteilten Bauch, auf dessen Höhe sich die Bettdecke, zum gänzlichen Niedergleiten bereit, kaum noch erhalten konnte. Seine vielen, im Vergleich zu seinem sonstigen Umfang kläglich dünnen Beine flimmerten ihm hilflos vor den Augen.","Quando Gregor Samsa una mattina si risvegliò da sogni inquieti, si ritrovò nel letto trasformato in un mostruoso insetto. Giaceva sulla schiena dura come una corazza e vedeva, sollevando appena la testa, il ventre bombato e bruno, suddiviso da irrigidimenti arcuati, sulla cui sommità la coperta riusciva a malapena a rimanere, pronta a scivolare del tutto. Le numerose zampe, pietosamente sottili rispetto alla mole del resto del corpo, gli tremolavano impotenti davanti agli occhi."],["»Was ist mit mir geschehen?« dachte er. Es war kein Traum, sein Zimmer, ein richtiges, nur etwas zu kleines Menschenzimmer, lag ruhig zwischen den vier wohlbekannten Wänden, über dem Tisch, auf dem eine auseinandergepackte Musterkollektion von Tuchwaren ausgebreitet war – Samsa war Reisender –, hing das Bild, das er vor kurzem aus einer illustrierten Zeitschrift ausgeschnitten und in einem hübschen, vergoldeten Rahmen untergebracht hatte.","«Che cosa mi è successo?», pensò. Non era un sogno: la sua stanza, una vera stanza umana, soltanto un poco troppo piccola, era tranquilla tra le quattro pareti ben note. Sopra il tavolo sul quale era sparsa una collezione di campioni di stoffe appena aperta – Samsa faceva il rappresentante – era appesa un’immagine che aveva ritagliato poco tempo prima da una rivista illustrata e sistemato in una graziosa cornice dorata."]]},{"id":"R3-C2-002","level":"C2","title":"Was ist Aufklärung? — Die Unmündigkeit","genre":"saggio filosofico autentico","sourceType":"public_domain","sourceUrl":"https://de.wikisource.org/wiki/Beantwortung_der_Frage:_Was_ist_Aufklärung%3F","sourceName":"Immanuel Kant, Beantwortung der Frage: Was ist Aufklärung? (1784)","period":"1784","pairs":[["Aufklärung ist der Ausgang des Menschen aus seiner selbst verschuldeten Unmündigkeit. Unmündigkeit ist das Unvermögen, sich seines Verstandes ohne Leitung eines anderen zu bedienen. Selbstverschuldet ist diese Unmündigkeit, wenn die Ursache derselben nicht am Mangel des Verstandes, sondern der Entschließung und des Muthes liegt, sich seiner ohne Leitung eines andern zu bedienen. Sapere aude! Habe Muth dich deines eigenen Verstandes zu bedienen! ist also der Wahlspruch der Aufklärung.","L’illuminismo è l’uscita dell’essere umano da uno stato di minorità di cui egli stesso è responsabile. La minorità è l’incapacità di servirsi del proprio intelletto senza la guida di un altro. Essa è imputabile a se stessi quando la sua causa non risiede nella mancanza di intelletto, ma nella mancanza di decisione e di coraggio di usarlo senza la guida altrui. Abbi il coraggio di sapere! Abbi il coraggio di servirti del tuo intelletto! Questo è dunque il motto dell’illuminismo."],["Faulheit und Feigheit sind die Ursachen, warum ein so großer Theil der Menschen, nachdem sie die Natur längst von fremder Leitung frei gesprochen, dennoch gerne Zeitlebens unmündig bleiben; und warum es Anderen so leicht wird, sich zu deren Vormündern aufzuwerfen. Es ist so bequem, unmündig zu sein. Habe ich ein Buch, das für mich Verstand hat, einen Seelsorger, der für mich Gewissen hat, einen Arzt der für mich die Diät beurtheilt, so brauche ich mich ja nicht selbst zu bemühen.","Pigrizia e viltà sono le ragioni per cui una parte così grande degli esseri umani, benché la natura li abbia da tempo liberati dalla guida altrui, preferisce rimanere in minorità per tutta la vita; ed è anche il motivo per cui è tanto facile per altri proporsi come loro tutori. È così comodo essere minorenni. Se possiedo un libro che pensa al posto mio, un consigliere spirituale che decide della mia coscienza, un medico che valuta la mia dieta, allora non devo più impegnarmi personalmente."]]},{"id":"R3-C2-003","level":"C2","title":"Der Sandmann — Ein verstörter Brief","genre":"estratto epistolare autentico","sourceType":"public_domain","sourceUrl":"https://de.wikisource.org/wiki/Der_Sandmann","sourceName":"E. T. A. Hoffmann, Der Sandmann (1816)","period":"1816","pairs":[["Gewiß seid Ihr alle voll Unruhe, daß ich so lange – lange nicht geschrieben. Mutter zürnt wohl, und Klara mag glauben, ich lebe hier in Saus und Braus und vergesse mein holdes Engelsbild, so tief mir in Herz und Sinn eingeprägt, ganz und gar. Dem ist aber nicht so; täglich und stündlich gedenke ich Eurer aller, und in süßen Träumen geht meines holden Klärchens freundliche Gestalt vorüber und lächelt mich mit ihren hellen Augen so anmutig an, wie sie wohl pflegte, wenn ich zu Euch hineintrat.","Sarete certamente tutti in grande apprensione perché è da tanto, tanto tempo che non scrivo. Mia madre sarà arrabbiata e Clara forse penserà che qui io viva tra feste e divertimenti, dimenticando del tutto la mia dolce immagine angelica, così profondamente impressa nel cuore e nei pensieri. Ma non è così: ogni giorno e ogni ora penso a tutti voi, e nei sogni più dolci mi appare la figura gentile della mia cara Clara, che mi sorride con i suoi occhi luminosi proprio come faceva quando entravo da voi."],["Ach, wie vermochte ich denn Euch zu schreiben in der zerrissenen Stimmung des Geistes, die mir bisher alle Gedanken verstörte! Etwas Entsetzliches ist in mein Leben getreten! Dunkle Ahnungen eines gräßlichen, mir drohenden Geschicks breiten sich wie schwarze Wolkenschatten über mich aus, undurchdringlich jedem freundlichen Sonnenstrahl.","Ah, come avrei potuto scrivervi nello stato lacerato del mio animo, che finora ha sconvolto ogni mio pensiero! Qualcosa di terribile è entrato nella mia vita! Oscuri presagi di un destino spaventoso che mi minaccia si stendono su di me come ombre di nuvole nere, impenetrabili a ogni raggio benevolo del sole."]]},{"id":"R3-C2-004","level":"C2","title":"Kleider machen Leute — Der Schneider","genre":"estratto letterario autentico","sourceType":"public_domain","sourceUrl":"https://de.wikisource.org/wiki/Kleider_machen_Leute","sourceName":"Gottfried Keller, Kleider machen Leute (1874)","period":"1874","pairs":[["An einem unfreundlichen Novembertage wanderte ein armes Schneiderlein auf der Landstraße nach Goldach, einer kleinen reichen Stadt, die nur wenige Stunden von Seldwyla entfernt ist. Der Schneider trug in seiner Tasche nichts, als einen Fingerhut, welchen er, in Ermangelung irgend einer Münze, unablässig zwischen den Fingern drehte, wenn er der Kälte wegen die Hände in die Hosen steckte, und die Finger schmerzten ihm ordentlich von diesem Drehen und Reiben.","In una giornata ostile di novembre un povero sartino percorreva la strada verso Goldach, una cittadina ricca distante poche ore da Seldwyla. Il sarto non portava in tasca altro che un ditale, che, non possedendo neppure una moneta, continuava a girare tra le dita quando, per il freddo, infilava le mani nei pantaloni; e le dita gli facevano davvero male per quel continuo rigirare e sfregare."],["Er hatte noch nichts gefrühstückt, als einige Schneeflocken, die ihm in den Mund geflogen, und er sah noch weniger ab, wo das geringste Mittagsbrod herwachsen sollte. Das Fechten fiel ihm äußerst schwer, ja schien ihm gänzlich unmöglich, weil er über seinem schwarzen Sonntagskleide, welches sein einziges war, einen weiten dunkelgrauen Radmantel trug.","Non aveva ancora fatto colazione, se non con alcuni fiocchi di neve che gli erano entrati in bocca, e ancor meno sapeva da dove sarebbe venuto il più piccolo pasto di mezzogiorno. Mendicare gli risultava estremamente difficile, anzi gli sembrava del tutto impossibile, perché sopra il vestito nero della domenica, l’unico che possedeva, portava un ampio mantello da viaggio grigio scuro."]]},{"id":"R3-C2-005","level":"C2","title":"Die Judenbuche — Recht und Gewohnheit","genre":"estratto letterario autentico","sourceType":"public_domain","sourceUrl":"https://de.wikisource.org/wiki/Die_Judenbuche","sourceName":"Annette von Droste-Hülshoff, Die Judenbuche (1842)","period":"1842","pairs":[["Friedrich Mergel, geboren 1738, war der einzige Sohn eines sogenannten Halbmeiers oder Grundeigenthümers geringerer Klasse im Dorfe B., das, so schlecht gebaut und rauchig es seyn mag, doch das Auge jedes Reisenden fesselt durch die überaus malerische Schönheit seiner Lage in der grünen Waldschlucht eines bedeutenden und geschichtlich merkwürdigen Gebirges.","Friedrich Mergel, nato nel 1738, era l’unico figlio di un cosiddetto piccolo proprietario terriero di categoria inferiore nel villaggio B., che, per quanto mal costruito e fumoso potesse essere, attirava comunque lo sguardo di ogni viaggiatore grazie alla straordinaria bellezza pittoresca della sua posizione in una gola boscosa di una catena montuosa importante e significativa dal punto di vista storico."],["Das Ländchen, dem es angehörte, war damals einer jener abgeschlossenen Erdwinkel ohne Fabriken und Handel, ohne Heerstraßen, wo noch ein fremdes Gesicht Aufsehen erregte, und eine Reise von dreißig Meilen selbst den Vornehmeren zum Ulysses seiner Gegend machte – kurz, ein Fleck, wie es deren sonst so viele in Deutschland gab, mit all den Mängeln und Tugenden, all der Originalität und Beschränktheit, wie sie nur in solchen Zuständen gedeihen.","La piccola regione alla quale apparteneva era allora uno di quegli angoli isolati senza fabbriche né commerci, senza grandi strade, dove un volto sconosciuto destava ancora scalpore e un viaggio di trenta miglia trasformava persino i più illustri in un Ulisse del luogo; in breve, un territorio come ce n’erano molti altri in Germania, con tutti i difetti, le virtù, l’originalità e la ristrettezza che possono prosperare soltanto in simili condizioni."]]},{"id":"R3-C2-006","level":"C2","title":"Das kalte Herz — Die Sehnsucht des Köhlers","genre":"estratto narrativo autentico","sourceType":"public_domain","sourceUrl":"https://de.wikisource.org/wiki/Das_kalte_Herz/Erste_Abteilung","sourceName":"Wilhelm Hauff, Das kalte Herz (1827)","period":"1827","pairs":[["Der junge Peter Munk, ein schlauer Bursche, ließ es sich gefallen, weil er es bei seinem Vater auch nicht anders gesehen hatte, die ganze Woche über am rauchenden Meiler zu sitzen oder, schwarz und berußt und den Leuten ein Abscheu, hinab in die Städte zu fahren und seine Kohlen zu verkaufen. Aber ein Köhler hat viel Zeit zum Nachdenken über sich und andere, und wenn Peter Munk an seinem Meiler saß, stimmten die dunkeln Bäume umher und die tiefe Waldesstille sein Herz zu Tränen und unbewußter Sehnsucht.","Il giovane Peter Munk, ragazzo astuto, accettava senza protestare, perché anche suo padre aveva vissuto così, di passare tutta la settimana accanto alla carbonaia fumante oppure di scendere in città, nero di fuliggine e sgradito alla gente, per vendere il carbone. Ma un carbonaio ha molto tempo per riflettere su se stesso e sugli altri; e quando Peter Munk sedeva accanto alla carbonaia, gli alberi scuri intorno e il profondo silenzio del bosco gli riempivano il cuore di lacrime e di un desiderio inconsapevole."],["Es betrübte ihn etwas, es ärgerte ihn etwas, er wußte nicht recht, was. Endlich merkte er sich ab, was ihn ärgerte, und das war – sein Stand. „Ein schwarzer, einsamer Kohlenbrenner!“ sagte er sich, „es ist ein elend Leben.“","Qualcosa lo rattristava, qualcosa lo irritava, e non sapeva bene che cosa fosse. Infine capì ciò che lo irritava: era la propria condizione. «Un carbonaio nero di fuliggine e solitario!», si disse, «è una vita miserabile»."]]}];
